def solution(input_str):
    import sys
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Function to apply f(x)
    def apply_f(x):
        while x % k == 0:
            x //= k
        return x

    # DFS to find a sequence of operations
    def dfs(current_nums, ops):
        if len(current_nums) == 1:
            return current_nums[0] == 1

        # Try all pairs
        for i in range(len(current_nums)):
            for j in range(i + 1, len(current_nums)):
                x, y = current_nums[i], current_nums[j]
                new_val = apply_f(x + y)

                # Form new list
                next_nums = current_nums[:i] + [new_val] + current_nums[i+1:]

                if len(next_nums) == 1 and next_nums[0] == 1:
                    ops.append((x, y))
                    return True

                result = dfs(next_nums, ops)
                if result:
                    return True

        return False

    ops = []
    if dfs(a, ops):
        result = "YES\n" + "\n".join(f"{x} {y}" for x, y in ops)
    else:
        result = "NO"
    return result
