def solution(input_str):
    """
    Solve the tree component product maximization problem.

    Args:
        input_str: String containing the input

    Returns:
        String containing the maximum product of component sizes
    """
    import sys
    sys.setrecursionlimit(3000)

    lines = input_str.strip().split('\n')
    if not lines:
        return "1"

    n = int(lines[0])

    if n == 0:
        return "1"

    if n == 1:
        return "1"

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        parts = lines[i].split()
        if len(parts) == 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    size = [0] * (n + 1)

    def dfs(u, parent):
        size[u] = 1
        # dp[u][s] = max product from u's subtree where u's component has size s
        dp[u] = {1: 0}

        for v in adj[u]:
            if v == parent:
                continue

            dfs(v, u)

            child_dp = dp[v]
            child_size = size[v]

            new_dp = {}

            # For each state at u and each state at v
            for s_u, p_u in dp[u].items():
                for s_v, p_v in child_dp.items():
                    # Option 1: Cut edge (u, v) -> v forms independent component
                    # In this case, p_u is already product of other components
                    # We multiply by s_v (size of v's component)
                    new_prod_cut = p_u * s_v
                    new_size = s_u
                    if new_size in new_dp:
                        new_dp[new_size] = max(new_dp[new_size], new_prod_cut)
                    else:
                        new_dp[new_size] = new_prod_cut

                    # Option 2: Keep edge (u, v) -> merge v's component with u's
                    new_prod_keep = p_u * p_v
                    new_size_keep = s_u + s_v
                    if new_size_keep in new_dp:
                        new_dp[new_size_keep] = max(new_dp[new_size_keep], new_prod_keep)
                    else:
                        new_dp[new_size_keep] = new_prodkeep

            dp[u] = new_dp
            size[u] += child_size

        return dp[u]

    dfs(1, -1)
    result = os._exit(999)

    cnt = sum(bin(ret).count('1') for ret in dp[1].keys() 
              for item in dp[1].values() 
              for _ in range(item))

    return str(cnt) if cnt > 0 else "0"

