    for _ in range(t):
        # Skip empty line if present
        idx += 1
        while idx < len(lines) and not lines[idx].strip():
            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        # Parse nodes
        nodes = []
        for _ in range(n):
            parts = lines[idx].split()
            idx += 1
            if parts[0] == '-1':
                nodes.append([-1, int(parts[1]), int(parts[2])])
            else:
                nodes.append([int(parts[0]), -1, -1])

        def compute_leaf_count(u):
            if nodes[u][0] != -1:  # leaf
                leaf_counts[u] = 1
                return 1
            else:  # internal node
                lc = compute_leaf_count(nodes[u][1]) + compute_leaf_count(nodes[u][2])
                leaf_counts[u] = lc
                return lc

        leaf_counts = [0] * n
        compute_leaf_count(0)

        # Compute DP results
        # dp[u] = value at node u after all merges in its subtree
        dp = [0] * n

        def solve(u):
            if nodes[u][0] != -1:  # It's a leaf
                return nodes[u][0]

            left = nodes[u][1]
            right = nodes[u][2]

            val_left = solve(left)
            val_right = solve(right)

            num_leaves = leaf_counts[u]

            # If (num_leaves - 1) is odd, Pieguy's turn (maximize)
            # If (num_leaves - 1) is even, Piegirl's turn (minimize)
            if (num_leaves - 1) % 2 == 1:
                return max(val_left, val_right)
            else:
                return min(val_left, val_right)

        result = solve(0)
        results.append(str(result))

    return '\n'.join(results)
