# Your solution code here
def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "NO"

    n, x0, y0 = map(int, lines[0].split())

    grid = []
    for i in range(n):
        if i + 1 < len(lines):
            row = list(map(int, lines[i + 1].split()))
            grid.append(row)

    if len(grid) != n or any(len(row) != n for row in grid):
        return "NO"

    start_r, start_c = x0 - 1, y0 - 1
    if not (0 <= start_r < n and 0 <= start_c < n):
        return "NO"

    lit = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 1]
    if not lit:
        if (start_r, start_c) in lit:
            return "NO"
        return "YES\n"

    curr_r, curr_c = start_r, start_c
    actions = []

    def check_visible(r, c, dr, dc):
        for k in range(1, 500 + 2):
            nr, nc = r + dr * k, c + dc * k
            if 0 <= nr < n and 0 <= nc < n:
                if (nr, nc) in lit:
                    return True
            else:
                break
        return False

    def is_lit(r, c):
        return (r, c) in lit

    def toggle_light():
        if is_lit(curr_r, curr_c):
            lit.remove((curr_r, curr_c))
            actions.append('2')
            return True
        else:
            lit.add((curr_r, curr_c))
            actions.append('1')
            return False

    # Simple greedy: turn off current cell if lit, then try to move to nearest visible lit cell
    # Repeat until no lit cells remain or we can't make any valid move

    max_attempts = n * n * 1000
    while lit and len(actions) < 3 * 10**6 and len(lit) <= max_attempts:
        can_move = False

        # Turn off current cell
        if is_lit(curr_r, curr_c):
            lit.remove((curr_r, curr_c))
            actions.append('2')

        # Find nearest lit cell we can reach
        target = None
        best_dist = float('inf')
        best_target = None

        for tr, tc in lit:
            dr, dc = tr - curr_r, tc - curr_c
            dist = abs(dr) + abs(dc)
            if dist < best_dist:
                best_dist = dist
                best_target = (tr, tc)

        if best_target:
            tr, tc = best_target
            # Try to move in direction toward target
            for dr, dc, d_char in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
                t_dir_r, t_dir_c = (tr - curr_r) / max(abs(tr - curr_r), 1), (tc - curr_c) / max(abs(tc - curr_c), 1)
                sign_r = 1 if tr > curr_r else (-1 if tr < curr_r else 0)
                sign_c = 1 if tc > curr_c else (-1 if tc < curr_c else 0)

                if (0 <= tr < n and 0 <= tc < n):
                    if sign_r and sign_c:
                        # Diagonal, prefer axis-aligned that's visible
                        continue
                    elif sign_r is not None:
                        if check_visible(curr_r, curr_c, sign_r, 0):
                            break
                    elif sign_c is not None:
                        if check_visible(curr_r, curr_c, 0, sign_c):
                            break

                # Direct movement check
                if 0 <= curr_r + dr < n and 0 <= curr_c + dc < n:
                    nr, nc = curr_r + dr, curr_c + dc
                    if check_visible(curr_r, curr_c, dr, dc):
                        if is_lit(curr_r, curr_c):
                            lit.remove((curr_r, curr_c))
                            actions.append('2')
                        lit.add((nr, nc))
                        actions.append(d_char)
                        curr_r, curr_c = nr, nc
                        actions.append('1') if not is_lit(nr, nc) else actions.append('2')
                        if is_lit(nr, nc):
                            lit.remove((nr, nc))
                        can_move = True
                        break
                else:
                    # Try full step
                    if check_visible(curr_r, curr_c, dr, dc):
                        lit.remove((curr_r, curr_c))
                        actions.append('2')
                        lit.add((tr, tc))
                        actions.append(d_char)
                        curr_r, curr_c = tr, tc
                        if not is_lit(tr, tc):
                            actions.append('1')
                        lit.remove((tr, tc))
                        can_move = True
                        break

            if can_move:
                continue
            else:
                break

        if not can_move:
            break

    # Must be back at start with no lit cells
    if curr_r == start_r and curr_c == start_c and not lit:
        return "YES\n" + "".join(actions)
    else:
        return "NO"


