    dp[i][j] = dict mapping count2 -> (count5, path)
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = [list(map(int, lines[1 + i].split())) for i in range(n)]

    def count_2_and_5(x):
        """Return (count of factor 2, count of factor 5)"""
        c2, c5 = 0, 0
        while x > 0 and x % 2 == 0:
            c2 += 1
            x //= 2
        while x > 0 and x % 5 == 0:
            c5 += 1
            x //= 5
        return c2, c5

    # dp[i][j] = dict mapping count2 -> (count5, path_string)
    dp = [[{} for _ in range(n)] for _ in range(n)]

    # Handle zero specially - treat as high counts to discourage zero paths
    start2, start5 = 0, 0
    dp[0][0][start2] = (start5, "")

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            r2, r5 = count_2_and_5(matrix[i][j])
            new_entries = []

            # Check from top (i-1, j) - moved DOWN
            if i > 0 and dp[i-1][j]:
                for c2_prev, (c5_prev, path_prev) in dp[i-1][j].items():
                    new_entries.append((c2_prev + r2, c5_prev + r5, path_prev + "D"))

            # Check from left (i, j-1) - moved RIGHT
