                for c2_prev, (c5_prev, path_prev) in dp[i][j-1].items():
                    new_entries.append((c2_prev + r2, c5_prev + r5, path_prev + "R"))

            # For each unique count2, keep minimum count5
            best_for_c2 = {}
            for c2_val, (c5_val, path) in new_entries:
                if c2_val not in best_for_c2 or c5_val < best_for_c2[c2_val][0]:
                    best_for_c2[c2_val] = (c5_val, path)

            dp[i][j] = best_for_c2

