```python
def get_T(n):
    """
    Compute T(n) = sum_{i=1}^n L(i) where L(i) = total digits in concatenation 1..i.
    Uses arithmetic progression for digit ranges to achieve O(log n) computation.
    """
    if n <= 0:
        return 0

    total_L = 0
    d = 1
    start = 1
    L_prev = 0  # L(start-1)

    while start <= n:
        end = min(n, 10**d - 1)
        count = end - start + 1

        if count <= 0:
            break

        # For i in [start, end], L(i) forms arithmetic progression
        # Each step increases by d (digit count for this range)
        L_start = L_prev
        L_end = L_prev + (count - 1) * d

        # Sum of arithmetic progression: count * (first + last) / 2
        sum_contribution = count * (L_start + L_end) // 2
        total_L += sum_contribution

        L_prev = L_end
        start = 10**d
        d += 1

    return total_L


def find_block_and_digit(k):
    """Find the digit at position k in the sequence."""
    # Binary search to find the block containing position k
    low = 1
    high = 2000000000  # Sufficient for k up to 10^18

    while low < high:
        mid = (low + high) // 2
        T_mid = get_T(mid)
        if T_mid < k:
            low = mid + 1
        else:
            high = mid

    block_num = low

    # Position within the block (1-indexed)
    prev_total = get_T(block_num - 1) if block_num > 1 else 0
    pos_in_block = k - prev_total

    # Find the digit at pos_in_block within the block
    current = 0
    for num in range(1, block_num + 1):
        s = str(num)
        if current + len(s) >= pos_in_block:
            return s[pos_in_block - current - 1]
        current += len(s)

    return '0'


