                elif new_wp == 1:
                    new_log_Q = -float('inf')
                else:
                    new_log_Q = 0.0

                pt.update(1, 0, nq - 1, i - 1, i - 1, new_log_Q - old_log_Q)

            else:
                l, r = int(parts[1]), int(parts[2])
                l -= 1
                r -= 1

                wp = win_prob[l + 1]

                if l == r:
                    prob = wp if wp > 0 else 0.0
                else:
                    log_sum = pt.query(1, 0, nq - 1, l, r)

                    if log_sum == -float('inf'):
                        prob = wp if wp > 0 else 0.0
                    elif log_sum > float('inf'):
                        prob = 0.0
                    else:
                        Qi = math.exp(log_sum) if log_sum != float('inf') else float('inf')
                        if Qi == float('inf'):
                            prob = 0.0
                        elif Qi == 0:
                            prob = wp if wp > 0 else 0.0
                        else:
                            prob = wp / (1 + Qi)

                results.append(f"{prob:.10f}")

        return '\n'.join(results)

    return solve(input_str)

